import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Словарь","description":"","frontmatter":{"pageId":"glossary","contentRevision":2},"headers":[],"relativePath":"ru/glossary.md","filePath":"ru/glossary.md"}'),o={name:"ru/glossary.md"};function i(l,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="словарь" tabindex="-1">Словарь <a class="header-anchor" href="#словарь" aria-label="Permalink to &quot;Словарь&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Термин</th><th>Значение</th></tr></thead><tbody><tr><td>Канонический сейв</td><td>Состояние колонии, принятое сервером</td></tr><tr><td>Эскроу</td><td>Предметы, пешки или серебро, удерживаемые сервером до исхода операции</td></tr><tr><td>Почта / посылка</td><td>Доставка и возврат эскроу получателю</td></tr><tr><td>Outbox</td><td>Локальный журнал неподтверждённых исходящих запросов</td></tr><tr><td>Live / хозяин / гость</td><td>Сессия живой карты с единственным авторитетным хозяином</td></tr><tr><td>Союз / гильдия</td><td>Социальная группа; гильдии используют существующие союзы</td></tr><tr><td>defName</td><td>Технический идентификатор типа предмета, например Steel</td></tr><tr><td>Scope</td><td>Набор прав административного API</td></tr><tr><td>Pin</td><td>Отпечаток доверенного TLS-сертификата</td></tr></tbody></table><h3 id="идентификаторы-восстановления" tabindex="-1">Идентификаторы восстановления <a class="header-anchor" href="#идентификаторы-восстановления" aria-label="Permalink to &quot;Идентификаторы восстановления&quot;">​</a></h3><ul><li><strong>SaveGeneration / поколение</strong>: линия жизни колонии; reset делает прежние локальные сейвы устаревшими.</li><li><strong>SaveWriteEpoch / эпоха записи</strong>: право записи в текущую временную линию; rollback меняет эпоху и отсекает старые сессии, не создавая новую колонию.</li><li><strong>Save version / версия сейва</strong>: номер серверного снимка; не версия программы и не generation/epoch.</li></ul><h2 id="state-terms" tabindex="-1">Какие термины нельзя смешивать при восстановлении? <a class="header-anchor" href="#state-terms" aria-label="Permalink to &quot;Какие термины нельзя смешивать при восстановлении? {#state-terms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Термин</th><th>Не путать с</th><th>Практическое следствие</th></tr></thead><tbody><tr><td>Версия Rimlink</td><td>Версия сейва</td><td>Обновление мода не выбирает снимок колонии</td></tr><tr><td>ProtocolVersion</td><td>Версия RimWorld</td><td>Проверяет сетевой контракт, не наличие DLC</td></tr><tr><td>SaveGeneration</td><td>SaveWriteEpoch</td><td>Reset создаёт новую жизнь колонии, rollback меняет право записи старой</td></tr><tr><td>escrow</td><td>Почта</td><td>Удерживаемое предложение ещё не доставлено получателю</td></tr><tr><td>request_id</td><td>id сделки</td><td>Повтор намерения использует тот же request_id</td></tr><tr><td>Host</td><td>Выделенный сервер</td><td>В live host — игра владельца карты, не серверный процесс</td></tr><tr><td>Tick</td><td>Реальные часы</td><td>Пауза карты не останавливает срок предложения на сервере</td></tr><tr><td>Альянс</td><td>Coop</td><td>Социальная группа не выдаёт управление пешками</td></tr></tbody></table><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Названия конфигурационных ключей, команд, кодов ошибок и defName не переводятся. Копия пешки в визите и реальная пешка рейда имеют разный риск.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./players/raids-incidents">Рейды и платные события</a></li><li><a href="./admins/security-auth">TLS, вход и права</a></li></ul>',12)])])}const b=d(o,[["render",i]]);export{m as __pageData,b as default};
